UPDATE companies SET description='Tomfoolery Wood Co. is based in Kent, Washington, with a workshop in Seattle where it designs and handcrafts solid wood furniture. The company does not publicly disclose its founding year or ownership structure, but its operation centers on Pacific Northwest craftsmanship.

The shop produces custom furniture including armoires, benches, bookcases, consoles, dressers, vinyl LP storage units, and tables. Each piece is built from responsibly sourced domestic hardwoods — Willamette Valley walnut, white oak, maple, cherry, madrone, and myrtle — selected by hand and finished with custom stain options. Hardware choices include solid brass pulls or wood edge accent pulls, and some compartments feature height-adjustable shelves. Production is done start-to-finish in the company’s own facility, though headcount and floor space are not disclosed.

The company emphasizes sustainability, partnering with regional mills and restoration projects to use salvaged urban and orchard trees, and employs waste-minimizing processes. Its differentiators include a collaborative design process, locally sourced materials with provenance, and a focus on heirloom-quality construction intended to last generations.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom solid wood furniture design", "Handcrafted manufacturing", "Wood species selection and milling", "Custom stain finishing", "Hardware installation (solid brass, wood pulls)", "Height-adjustable shelf integration", "Salvaged wood sourcing", "Waste-minimizing fabrication"], "industries": ["Furniture manufacturing", "Custom furniture"], "materials": ["Willamette Valley walnut", "White oak", "Maple", "Cherry", "Madrone", "Myrtle", "Solid brass", "Wood (for pulls)"], "equipment": [], "volume": "", "lead_time": "Approximately 17 weeks to order fulfillment; 8\u201312 weeks to production start", "tolerances": "", "built_on": ["Responsibly sourced Pacific Northwest hardwoods", "Waste-minimizing production processes", "Custom stain finishes and premium hardware options", "Collaborative, start-to-finish design and build", "Handcrafted in Seattle workshop"], "facts_used": ["Kent, Washington headquarters -> db", "Seattle workshop -> /about", "Handcrafted solid wood furniture -> /, /about", "Product list: armoires, benches, bookcases, consoles, dressers, vinyl LP storage, tables -> /", "Wood species: Willamette Valley walnut, white oak, maple, cherry, madrone, myrtle -> /about", "Solid brass or wood pulls -> /about, products", "Height adjustable shelves -> products", "Lead time ~17 weeks to fulfillment -> /, /about", "Lead time 8-12 weeks to production start -> products", "Custom stain options -> /about", "Waste-minimizing processes -> /about", "Collaborative design process -> /about", "Salvaged urban/orchard trees -> /about", "Testimonials from Seattle, Drury MO, Portland -> /about", "No founding year stated -> db", "No ownership tags stated -> db", "No employee count stated -> db", "No certifications stated -> db", "No equipment named -> db", "No volume range stated -> db", "No tolerances stated -> db", "No min order stated -> db", "No export compliance stated -> db", "No languages stated -> db", "No social links in input -> db", "Company type evidence: ''Custom Solid Wood Furniture Design/Manufacturing'' -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Custom Solid Wood Furniture Design/Manufacturing", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='tomfoolery-wood-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Tonka Electronics, Inc. was founded on September 1, 1976 in Bloomington, Minnesota, as a manufacturer''s representative and stocking distributor for the printed circuit board fabrication and assembly industry. The woman-owned small business was incorporated in Minnesota by founder Mike DeLadi, who established the company on a principle of "No slogans, just service."

The company represents capital equipment lines and supplies the consumables those machines require, including leaded and lead-free solder bar, wire, and paste, fluxes, flux additives, solder masks, and cleaning agents. It operates a fully stocked warehouse and offers services such as "SmartDry" intelligent dry storage for SMT component reels, SMT placement equipment, solder analysis, specialty coating systems, and low-cost resharpening. As a manufacturer''s representative, its territory covers Minnesota, North and South Dakota, northwest Wisconsin, and parts of Iowa; as a distributor it ships nationwide.

Tonka serves the printed circuit board fabrication and assembly sector, with additional involvement in the medical industry through fine hard wire cutting tools. Its customers are electronics manufacturers seeking process development support and equipment implementation, and it also sells SpliceRite-branded SMT tape splicing products, cover tape extenders, and carrier tape cutting tools directly via e-commerce.

The founder''s motto, "No slogans, just service," underscores a focus on hands-on support rather than marketing. The company describes itself as a "focused" distributor specializing in soldering and cleaning products, and emphasizes close collaboration with customers during new equipment installation and process development.', certifications=ARRAY['Woman-owned small business']::text[], profile='{"capabilities": ["Manufacturer''s representation for PCB fabrication and assembly equipment", "Stocking distribution of solder and cleaning consumables", "SmartDry intelligent dry storage solutions", "SMT placement equipment supply", "Solder analysis services", "Specialty coating systems", "Low-cost resharpening services", "Process development and equipment implementation support", "SpliceRite SMT tape splicing products", "Cover tape extenders and carrier tape cutting tools", "Ionograph and OmegaMeter ionic contamination testing solutions", "Electrovert equipment kits and spare parts"], "industries": ["Printed circuit board fabrication and assembly", "Medical"], "materials": ["Leaded solder bar", "Leaded solder wire", "Leaded solder paste", "Lead-free solder bar", "Lead-free solder wire", "Lead-free solder paste", "Fluxes", "Flux additives", "Solder masks", "Cleaning agents"], "equipment": ["SMT placement equipment", "OvenRIDER portable wave and oven optimizer", "OvenWATCH continuous quality monitor", "SmartDry intelligent storage and retrieval systems", "Electrovert spray fluxers", "Electrovert convection preheaters", "Electrovert chip waves", "Electrovert nitrogen nozzles", "Ionograph ionic contamination testing systems", "OmegaMeter ionic contamination testing systems", "SpliceRite carrier tape cutting and splicing tools"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["\"No slogans, just service\" founding principle", "Focused distributor specializing in soldering and cleaning products", "Fully stocked warehouse with leaded and lead-free solder alloys", "