UPDATE companies SET description='Town & Country Furniture operates as a family-owned furniture retailer in Dayton, Virginia, where it has served the Shenandoah Valley for more than 35 years. The business was founded on a commitment to offering heirloom-quality solid wood pieces, primarily sourced from Amish and American makers, at straightforward everyday pricing.

The store carries collections from several established manufacturers, including Windy Valley Outdoor, La-Z-Boy, Zimmerman Chair, and Mount Eden Woodworks. Its showroom spans living room, dining room, bedroom, home office, children''s room, and outdoor categories. In addition to sales, the company provides delivery and setup service performed by its own staff.

The customer base consists of residential buyers throughout the Shenandoah Valley region seeking solid wood and Amish-crafted furniture.

The company emphasizes its no-sale pricing philosophy and family-operated service as key differentiators, aiming to simplify the purchasing experience for homeowners furnishing their primary residences.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Furniture retail", "Delivery and installation", "Multi-brand product curation"], "industries": ["Residential furniture", "Home furnishings"], "materials": ["Solid wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Delivery and setup included, performed by company staff", "Focus on heirloom-quality solid wood, Amish-made and American-made furniture", "Family-owned and operated in the Shenandoah Valley for over 35 years"], "facts_used": ["Family owned and operated furniture store -> db", "Served Shenandoah Valley of Virginia for over 35 years -> db", "Headquarters in Dayton, Virginia -> db", "Carries brands: Windy Valley Outdoor, La-Z-Boy, Zimmerman Chair, Mount Eden Woodworks -> /", "Offers heirloom quality solid wood Amish Made and American Made furniture -> /", "No sale pricing policy -> /", "Delivery and setup by company staff -> /", "Product categories: Living Room, Dining Room, Children''s Room, Home Office, Bedroom, Outdoors -> /"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "Town and Country Furniture is a family owned and operated furniture store", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='town-country-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='Toyota Boshoku Kentucky operates a manufacturing facility in Harrodsburg, Kentucky. The facility focuses on seat systems and interior components for vehicle manufacturers.

The plant employs proprietary processes including Simultaneous Back-Injection Molding Technology and Fine Hold Stamping Method to produce automobile seats, aircraft seats, door trims, headliners, floor carpets, luggage compartments, and exterior components. It also manufactures plastic parts for internal combustion engines and electric vehicles, as well as textile components. The operation integrates product engineering, production engineering, and testing capabilities such as driving simulators and proving grounds.

The facility supplies components for both traditional internal combustion engine platforms and electric vehicle programs.

Toyota Boshoku states its development process is founded in human factors and ergonomics, aiming to deliver seats that support comfortable driving posture, adapt to body variations, and reduce fatigue on long drives. The company highlights technologies such as Foam In Place Method and lightweight molded foam door trims with high impact resistance as part of its differentiation.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Simultaneous Back-Injection Molding", "Fine Hold Stamping", "Foam In Place Method", "Seat design and engineering", "Interior component manufacturing", "Exterior component manufacturing", "Plastic injection molding", "Stamping", "Textile component manufacturing", "Product engineering", "Production engineering", "Testing and evaluation (driving simulator, proving ground)"], "industries": ["Automotive", "Aerospace", "Electric vehicles"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Human factors and ergonomics-based seat development", "Simultaneous Back-Injection Molding Technology", "Fine Hold Stamping Method", "Foam In Place Method", "Lightweight molded foam door trim with high impact resistance"], "facts_used": ["Location: Harrodsburg, Kentucky -> db", "Capabilities: Simultaneous Back-Injection Molding Technology, Fine Hold Stamping Method -> db", "Products: Automobile Seats, Aircraft seats, Door Trims, Floor Carpets, Luggage Compartment, Exterior Components, Plastic Parts for ICE, Products for Electric Vehicles, Textile Components -> db", "Description: Human factors and ergonomics-based seat development -> db", "Global corporate website: toyota-boshoku.com -> /", "Additional technologies: Foam In Place Method, Lightweight Molded Foam Door Trim, Driving Simulator, Proving Ground -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Automobile Seats, Aircraft seats, Door Trims, Floor Carpets, Luggage Compartment, Exterior Components, Plastic Parts for I